/**
 * FirstPersonCamera - FPS-style camera with pointer lock
 *
 * Extends PhysicsCamera to provide first-person shooter camera controls.
 * Automatically manages pointer lock, accumulates yaw/pitch rotation,
 * and syncs body rotation for WASD movement in the look direction.
 *
 * @class FirstPersonCamera
 * @extends PhysicsCamera
 * @short FPS-style camera with pointer lock and physics sync.
 * @category Camera
 * @tags Physics, Camera, FPS, WebGPU, WebGL
 *
 * @example
 * import { FirstPersonCamera } from '@three-blocks/pro';
 *
 * const camera = new FirstPersonCamera(physics, {
 *   canvas: renderer.domElement,
 *   target: playerMesh,
 *   eyeHeight: 1.7,
 *   sensitivity: { x: 2, y: 2 },
 * });
 *
 * // In animate loop
 * camera.update(delta);
 * renderer.render(scene, camera);
 */
export class FirstPersonCamera extends PhysicsCamera {
    /**
     * Create a FirstPersonCamera.
     *
     * @param {Object} physics - Physics instance
     * @param {Object} [options={}] - Camera options
     * @param {HTMLCanvasElement} options.canvas - Canvas element for pointer lock
     * @param {THREE.Object3D} [options.target] - Player mesh to follow (auto-detects body index from mesh.userData)
     * @param {number} [options.playerBodyIndex] - Explicit body index to follow (overrides auto-detection)
     * @param {number} [options.eyeHeight=1.7] - Eye height offset from target position
     * @param {Object} [options.sensitivity={ x: 2, y: 2 }] - Mouse sensitivity
     * @param {number[]} [options.pitchLimits=[-85, 85]] - Vertical look limits in degrees
     * @param {number} [options.fov=70] - Field of view
     */
    constructor(physics: any, options?: {
        canvas: HTMLCanvasElement;
        target?: THREE.Object3D;
        playerBodyIndex?: number;
        eyeHeight?: number;
        sensitivity?: any;
        pitchLimits?: number[];
        fov?: number;
    });
    /**
     * Canvas element for pointer lock.
     * @type {HTMLCanvasElement}
     */
    canvas: HTMLCanvasElement;
    /**
     * Eye height offset from target position.
     * @type {number}
     */
    eyeHeight: number;
    /**
     * Mouse sensitivity for rotation.
     * @type {{ x: number, y: number }}
     */
    sensitivity: {
        x: number;
        y: number;
    };
    /**
     * Vertical look limits in degrees [min, max].
     * @type {number[]}
     */
    pitchLimits: number[];
    _yaw: number;
    _pitch: number;
    _locked: boolean;
    _onMouseMove: any;
    _onPointerLockChange: any;
    _onClick: any;
    _yawQuat: any;
    _pitchQuat: any;
    _destQuat: any;
    _callbacks: {
        lock: any[];
        unlock: any[];
    };
    /**
     * Set up event listeners for pointer lock and mouse movement.
     * @private
     */
    private _setupListeners;
    _eventTarget: Document | HTMLCanvasElement;
    /**
     * Handle canvas click - request pointer lock.
     * @private
     */
    private _handleClick;
    /**
     * Handle pointer lock state changes.
     * @private
     * @param {Event} event
     */
    private _handlePointerLockChange;
    /**
     * Handle mouse movement - rotate camera.
     * @private
     * @param {MouseEvent} event
     */
    private _handleMouseMove;
    /**
     * Register an event callback.
     *
     * @param {'lock'|'unlock'} event - Event name
     * @param {Function} callback - Callback function
     * @returns {this} For chaining
     */
    on(event: "lock" | "unlock", callback: Function): this;
    /**
     * Remove an event callback.
     *
     * @param {'lock'|'unlock'} event - Event name
     * @param {Function} callback - Callback to remove
     * @returns {this} For chaining
     */
    off(event: "lock" | "unlock", callback: Function): this;
    /**
     * Emit an event to registered callbacks.
     * @private
     * @param {'lock'|'unlock'} event
     */
    private _emit;
    /**
     * Whether pointer lock is currently active.
     * @type {boolean}
     */
    get locked(): boolean;
    /**
     * Current yaw angle in radians.
     * @type {number}
     */
    get yaw(): number;
    /**
     * Current pitch angle in radians.
     * @type {number}
     */
    get pitch(): number;
    /**
     * Set the yaw angle (horizontal rotation).
     *
     * @param {number} radians - Yaw angle in radians
     * @returns {this} For chaining
     */
    setYaw(radians: number): this;
    /**
     * Set the pitch angle (vertical rotation).
     *
     * @param {number} radians - Pitch angle in radians
     * @returns {this} For chaining
     */
    setPitch(radians: number): this;
    /**
     * Manually request pointer lock.
     */
    lock(): void;
    /**
     * Exit pointer lock.
     */
    unlock(): void;
}
import { PhysicsCamera } from './PhysicsCamera.js';
